{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.noos_visibility as WITH noos_pre AS ( SELECT upper(trim(SUBSTRING(\"SKU\", 2))) AS sku_group, remarks, TO_DATE(REPLACE(revised_delivery_date::text, \'/\', \'-\'),\'DD-MM-YYYY\') AS revised_delivery_date, Projected_QTY as proj_qty, row_number() over (partition by upper(trim(SUBSTRING(\"SKU\", 2))) order by TO_DATE(REPLACE(revised_delivery_date::text, \'/\', \'-\'),\'DD-MM-YYYY\') asc) as production_stage FROM snitch_db.maplemonk.gs_noos_nos_mp where TO_DATE(REPLACE(revised_delivery_date::text, \'/\', \'-\'),\'DD-MM-YYYY\') >= \'2025-06-01\' ), noos as ( select sku_group, max(case when production_stage = 1 then revised_delivery_date end) as first_prod_delivery_date, max(case when production_stage = 2 then revised_delivery_date end) as second_prod_delivery_date, max(case when production_stage = 3 then revised_delivery_date end) as third_prod_delivery_date, sum(case when production_stage = 1 then proj_qty end) as first_prod_qty, sum(case when production_stage = 2 then proj_qty end) as second_prod_qty, sum(case when production_stage = 3 then proj_qty end) as third_prod_qty, max(production_stage) as production_stage from noos_pre group by 1 ), metafield_data AS ( SELECT sku_group, print_design, collar, fit, category, sellable_inventory, sleeve_type, color, vendor, material_new FROM snitch_db.maplemonk.metafields_data qualify row_number() over (partition by sku_group order by status desc) = 1 ), main as ( SELECT a.*, print_design, collar, fit, category, sellable_inventory, sleeve_type, color, vendor, material_new FROM noos a LEFT JOIN metafield_data b ON a.sku_group = b.sku_group ), inwards_details as ( select sku_group, inward_date, inventory_on_inward_date, is_ros_hit, ros from snitch_db.maplemonk.original_ros_str_eoq where inward_date>= \'2025-06-01\' ), total_inwards as ( select sku_group, count(inward_date) as inward_freq from inwards_details group by 1 ), main_data as ( select a.*,b.inward_freq as inward_stage, row_number() over (partition by a.sku_group order by inward_date asc) as inward_rank from inwards_details a left join total_inwards b on a.sku_group = b.sku_group ), inwards_final as ( select sku_group, max(case when inward_rank = 1 then inward_date end) as first_inward_date, max(case when inward_rank = 2 then inward_date end) as second_inward_date, max(case when inward_rank = 3 then inward_date end) as third_inward_date, sum(case when inward_rank = 1 then inventory_on_inward_date end) as first_inward_inv, sum(case when inward_rank = 2 then inventory_on_inward_date end) as second_inward_inv, sum(case when inward_rank = 3 then inventory_on_inward_date end) as third_inward_inv, sum(case when inward_rank = 1 then ros end) as first_inward_ros, sum(case when inward_rank = 2 then ros end) as second_inward_ros, sum(case when inward_rank = 3 then ros end) as third_inward_ros, max(inward_stage) as inward_stage from main_data group by 1 ), images_data as ( SELECT LEFT(variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION(\'-\' IN REVERSE(variant.value:sku::STRING))) AS sku_group, image.value:\"preview\":\"image\":\"url\"::string AS image_url, FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => parse_json(t.media)) AS image, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) AS variant, WHERE image.value:\"mediaContentType\"::string = \'IMAGE\' qualify ROW_NUMBER() OVER (PARTITION BY t.id ORDER BY image.index) = 1 ), nos_channel as ( select upper(trim(sku_group)) as sku_group, tag as nos_channel from snitch_db.maplemonk.gs_final_moq ), prod_details as ( select sku_group, category, product_name from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by sku_group order by status desc) = 1 ), weighted_avg_ros as ( select sku_group, div0(sum(inventory_on_inward_date*ros),sum(inventory_on_inward_date)) as ros from snitch_db.maplemonk.original_ros_str_eoq group by 1 ), clicks_pre as ( select ga_date, sku_group, sum(clicks) as clicks from snitch_db.maplemonk.clicks_itemid group by 1,2 ), main_pre as ( select a.*, first_inward_date, second_inward_date, third_inward_date, first_inward_inv, second_inward_inv, third_inward_inv, first_inward_ros, second_inward_ros, third_inward_ros, inward_stage,e.product_name,f.ros,c.image_url,d.nos_channel from main a left join inwards_final b on a.sku_group = b.sku_group left join images_data c on a.sku_group = c.sku_group left join nos_channel d on a.sku_group = d.sku_group left join prod_details e on a.sku_group = e.sku_group left join weighted_avg_ros f on a.sku_group = f.sku_group ), clicks_pre_calc as ( select a.*, first_inward_date, second_inward_date, third_inward_date, inward_stage, from clicks_pre a left join main_pre b on a.sku_group = b.sku_group where a.sku_group in (select sku_group from main_pre) ), inwards_clicks as ( select sku_group, (div0(sum(case when ga_date>= first_inward_date and ga_date<=coalesce(second_inward_date,current_date) then clicks end),max(datediff(day,first_inward_date,coalesce(second_inward_date,current_date-1)))))::int as first_roc, (div0(sum(case when ga_date>= second_inward_date and ga_date<=coalesce(third_inward_date,current_date) then clicks end), max(datediff(day,second_inward_date,coalesce(third_inward_date,current_date-1)))))::int as second_roc, (div0(sum(case when ga_date>= third_inward_date and ga_date<=current_date then clicks end),max(datediff(day,third_inward_date,current_date-1))))::int as third_roc, from clicks_pre_calc group by 1 ) select a.*, first_roc, second_roc, third_roc from main_pre a left join inwards_clicks b on a.sku_group = b.sku_group ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            